"""Three new silhouette prototypes, intentionally not installed."""
from pathlib import Path
import sys,uuid
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'hd-cave-wall-variety-20261115'))
import pipeline as w
p=w.p;R=w.R;OUT=R/'assets/generated/v13ent-vault-rock-prototypes/v1-20261115';p.OUT=OUT
DESIGNS={
 'a':'A: A very NARROW clean natural rock margin beside the metal frame. Recede the entire upper and middle left outline to the RIGHT, leaving generous exposed metal in the neighboring scene. Use one solid continuous slightly slanted edge without fingers, hooks, overhangs, suspended tips or a hollow bite. The upper two thirds are compact and narrow; at the bottom only a small blunt rock foot with a bevelled fractured surface, NOT a protruding snout. Shallow irregular diagonal laminar chips in the surface. Most restrained silhouette.',
 'b':'B: A compact continuous LAYERED BUTTRESS of exactly three broad thick stone ledges, each firmly attached to the one behind and below it. Three blunt broken step transitions on the left side, no thin pointed pieces. The steps must be distinctly different from a flat slope but broad and structurally credible. The upper ledge retreats away from the metal door; the middle ledge is solid, not a dangling stalactite. Keep the lower foot compact, with no projecting nose or black mouth. Coarse rough fractured layered stone, shallow crevices only.',
 'c':'C: A single connected SLANTED FRACTURE FACE with one broad diagonal planar break from upper-left toward lower-right, then a short compact base. A simple uninterrupted bevelled LEFT contour with a gentle inward bow. Bold large flat fractured stone planes cut by a few shallow diagonal cracks, no ledges or stacks. Clearly different from a layered buttress. No horns, points, separated stones, nose, hollow, hanging spikes or holes. The shape meets the neighboring wall on its straight RIGHT cut edge.'}

def run(name):
 variant=name[0]
 d=OUT/name
 if (d/'run.json').exists():p.execute(d,{},{});return
 g={};outputs={};prefix='fallout1_vault_rock_prototypes/'+name+'-'+uuid.uuid4().hex
 def add(kind,**kw):k=str(len(g)+1);g[k]=p.node(kind,**kw);return [k,0]
 def load(path):return add('LoadImage',image=p.upload(path))
 def save(im,file):k=add('SaveImage',images=im,filename_prefix=prefix+'/'+file);outputs[k[0]]=file+'.png'
 old=load(OUT/'inputs/original.png');old=add('JoinImageWithAlpha',image=old,alpha=[old[0],1]);old=add('ImageScale',image=old,upscale_method='lanczos',width=248,height=960,crop='disabled')
 canvas=add('EmptyImage',width=384,height=1024,batch_size=1,color=0);empty=add('SolidMask',value=1.,width=384,height=1024);canvas=add('JoinImageWithAlpha',image=canvas,alpha=empty);canvas=add('ImageCompositeMasked',destination=canvas,source=old,x=68,y=32,resize_source=False);save(canvas,'input')
 if name.endswith('-v2') or name=='b-v3':
  revised=load(OUT/'a/prototype.png');canvas=add('JoinImageWithAlpha',image=revised,alpha=[revised[0],1])
 context=load(OUT/'inputs/door-context.png');rock=load(R/'assets/generated/v13ent-cave-variety/style-match-v2-20261115/selected/geo-rock-07.png');rock=add('JoinImageWithAlpha',image=rock,alpha=[rock[0],1])
 prompt='''Completely REDESIGN the SHAPE AND SILHOUETTE of the rock wall fragment in image 1. The existing silhouette is explicitly REJECTED. This is NOT a texture-only edit. Image 2 shows why: it intrudes over the right metal frame of a Fallout vault doorway with long ugly pointed hanging teeth and a snout-like lower projection. Remove those protrusions and remove the black mouth/hole. Create ONE continuous narrow rock-wall SLICE attached to the cave wall on the RIGHT, not a standalone pillar, sculpture, tower or loose rock. The RIGHT cut edge must stay at the same x position near x=316, overall height stays from y=32 to y=992, the upper/lower anchors stay in place. The LEFT outline must be substantially redesigned and less intrusive than the input. Leave transparent space to the left. Do NOT draw the door, metal, background, floor, other stones, labels, plants or mushrooms in the output. Only the redesigned rock fragment on a transparent background. Use the SECOND image for isometric orientation/contact context only, and the THIRD for the approved material: dark neutral grey hard rough Fallout cave stone, coarse irregular strata, crisp chips and subdued grey mineral grain. Keep matching dark grey color and original lighting. Blunt silhouette does NOT mean soft material: no melted clay, wax, plastic, smooth polished pebble, cartoony stone, glossy highlights, blue tint or pale rock. The material remains rough and brittle, while the silhouette becomes simpler and firmly connected. Preserve scale and direction of the attached right-hand wall. NEW GEOMETRY: '''+DESIGNS[variant]
 if name.endswith('-v2'):
  prompt='''Redesign the SINGLE continuous narrow cave wall margin in image 1 into a thicker naturally fractured compact rock edge. Keep its uninterrupted simple LEFT contour, straight clipped RIGHT attachment edge at x316, transparent empty background, isometric view, neutral dark grey material and lighting. Extend its top to y32 and its base to y992. A solid narrow piece of cave wall, connected continuously at EVERY height, with no interior holes and no hanging or detached parts. Image 2 is door contact context ONLY, image 3 is hard rough stone material reference ONLY. Produce only the rock sprite; do not draw the door or any metal. The new geometry should consist of three broad uneven naturally overlapping stone PLATES of unequal sizes, fractured along slanted diagonal planes. These are shallow thick layers on a solid underlying wall, not a staircase: no horizontal treads, uniform steps, right-angled stair geometry, masonry, sharp descending tips, horns or narrow appendages. Keep all left-side protrusions short and blunt, firmly supported by the body beneath them. A compact blunt foot at bottom. Thick irregular grey mineral facets, rough grain and small sharp surface chips, while the OUTER contour stays calm and solid. Different from the very narrow flat original, but no more than twice its width. No black cavity, mouth or snout. No moss, fungi, new objects, text or frame.'''
  if variant=='c':
   prompt='''Create a substantially wider version of the SINGLE continuous solid cave wall margin in image 1. It is one SIMPLE SLANTED ROCK FACE, with one broad diagonal fracture plane and a quiet continuous bevelled left contour. Think of a thick edge of a large natural grey rock slab attached to an unseen cave wall on its right. Keep its straight clipped RIGHT edge at x316, top at y32 and bottom at y992, on a transparent background. Widen its upper and middle body toward x140-180, and form a single gently sloping uninterrupted LEFT outline that recedes toward x205 in the middle and ends in a compact blunt flat foot. One solid mass at EVERY height: no branching, no overhang, no hanging fingers, no hook, no cut-out, no void, no hole, no projecting nose. The old small side protrusions are removed. Large diagonal stone planes, two restrained diagonal surface fractures, small rough mineral grain. Hard charcoal-grey fractured stone matching image 3, neutral grey and original subdued lighting. No bright highlights, blue tint, clay softness, stacked ledges, stair steps, crystals, vegetation or extra objects. Image 2 is only the orientation/contact reference with the metal doorway; DO NOT draw any door, metal or background in the output. Only one isolated solid cave-wall slice with its new simple broad angular silhouette, at original scale and camera.'''
 if name=='b-v3':
  revised=load(OUT/'c-v2/prototype.png');canvas=add('JoinImageWithAlpha',image=revised,alpha=[revised[0],1]);save(canvas,'geometry-reference')
  prompt='''Edit the solid rock slab in image 1 into a thick layered edge of a natural cave wall. Change the outer LEFT silhouette: replace its long simple diagonal edge with THREE LARGE BLUNT ANGULAR MASSIVE FACETS. The top must be wide and blunt, not a sharp tip. The upper third is a thick rectangular rough stone block extending LEFT toward x190; the middle third extends left toward x150; the bottom third steps back to x200. Each transition is an uneven short oblique broken bevel, not a horizontal stair. The entire shape is solid from top to bottom, backed continuously by a straight RIGHT edge at x326. Keep height y40 to y944. Keep the overall broad slab thickness. No dangling fingers, teeth, horns, spikes, long tapering tips, voids, mouths, holes, projecting snout or branching parts. Surface: HARD BRITTLE coarse neutral charcoal grey fractured rock with irregular diagonally layered mineral flakes and sharp small chips, same cave stone color and roughness as image 3. NOT soft clay, not smooth polished rock. Image 2 shows door orientation only: output ONLY the stone sprite on a transparent background, no metal or environment. Substantially different silhouette: three large solid uneven block-like facets with blunt broken corners, structurally continuous mass.'''
 model=add('UNETLoader',unet_name='qwen_image_2.1_int8_convrot.safetensors',weight_dtype='default');clip=add('CLIPLoader',clip_name='qwen3vl_8b_int8_convrot.safetensors',type='qwen_image',device='default');vae=add('VAELoader',vae_name='qwen_image_2.1_vae_bf16.safetensors');model=add('QwenImage21Cache',model=model,device='cpu',dtype='default')
 enc=add('TextEncodeQwenImage21',clip=clip,prompt=prompt,negative_prompt='',vae=vae,resolution=0,**{'images.image_1':canvas,'images.image_2':context,'images.image_3':rock})
 sample=add('KSampler',model=model,positive=enc,negative=[enc[0],1],latent_image=[enc[0],2],seed=15122000+ord(variant)+(100 if name.endswith('-v2') else 0),steps=25,cfg=1.,sampler_name='euler',scheduler='simple',denoise=1.)
 result=add('VAEDecode',samples=sample,vae=vae);save(result,'prototype')
 d.mkdir(parents=True,exist_ok=True);(d/'prompt.txt').write_text(prompt,encoding='utf-8');p.save(d/'registration.json',dict(reference_sprite_in_canvas=[68,32,248,960],canvas=[384,1024],preview_scale_to_hd=.5,preview_offset_from_old_hd=[-34,-16],status='prototype only; new alpha retained, not installed'))
 p.execute(d,g,outputs)

if __name__=='__main__':
 for name in (sys.argv[1:] or list(DESIGNS)):run(name)
